fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Requires: The indices i, j, and k must be valid indices for the valores vector.
    // Ensures: The returned tuple contains the indices of the two largest values in valores.
    // The first index corresponds to the largest value, and the second index corresponds to the second largest value.
    // The function maintains the invariant that the indices are within bounds of the valores vector.
    // Decreases: The length of the indices_values vector is always 3, so no decrease clause is necessary.

    // Create a vector of tuples containing the indices and their corresponding values
    let mut indices_values = vec![(i, valores[i]), (j, valores[j]), (k, valores[k])];

    // Sort the vector by values in descending order
    indices_values.sort_by(|a, b| b.1.cmp(&a.1));

    // The first two indices in the sorted vector are the ones we want to return
    let (first_index, _) = indices_values[0];
    let (second_index, _) = indices_values[1];

    (first_index, second_index)
}

